e", "price_field", "price", "source", "kind", "direction"], "title": "Trigger", "type": "object"}, "TriggerSource": {"additionalProperties": false, "properties": {"timeframe": {"title": "Timeframe", "type": "string"}, "bar_index": {"minimum": 0, "title": "Bar Index", "type": "integer"}, "open_time_ms": {"minimum": 0, "title": "Open Time Ms", "type": "integer"}, "close_time_ms": {"minimum": 0, "title": "Close Time Ms", "type": "integer"}}, "required": ["timeframe", "bar_index", "open_time_ms", "close_time_ms"], "title": "TriggerSource", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.trade-intent.v2", "title": "Schema", "type": "string"}, "role": {"const": "TRADER", "title": "Role", "type": "string"}, "decision": {"enum": ["ENTER_LONG", "ENTER_SHORT", "NO_TRADE"], "title": "Decision", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "market_context": {"anyOf": [{"additionalProperties": true, "type": "object"}, {"type": "null"}], "title": "Market Context"}, "setup": {"anyOf": [{"$ref": "#/$defs/Setup"}, {"type": "null"}]}, "decision_timeframe": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Decision Timeframe"}, "context_timeframes_used": {"items": {"type": "string"}, "title": "Context Timeframes Used", "type": "array"}, "entry_mechanism": {"enum": ["continuation", "breakout", "breakout_pullback", "reversal", "none", "unclear"], "title": "Entry Mechanism", "type": "string"}, "trigger": {"anyOf": [{"$ref": "#/$defs/Trigger"}, {"type": "null"}]}, "invalidation": {"anyOf": [{"$ref": "#/$defs/PriceReference"}, {"type": "null"}]}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}, "qualitative_confidence": {"enum": ["high", "medium", "low"], "title": "